
*{box-sizing:border-box} html{scroll-behavior:smooth}
body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Helvetica Neue","Noto Sans JP",Arial,sans-serif;color:#17324d;background:#fff;line-height:1.8}
a{color:inherit;text-decoration:none}
header{position:fixed;z-index:20;top:0;left:0;right:0;height:74px;display:flex;align-items:center;justify-content:space-between;padding:0 5vw;background:rgba(255,255,255,.92);backdrop-filter:blur(12px);border-bottom:1px solid #dceefa}
.logo{font-size:25px;font-weight:800;letter-spacing:-1px}.nav{display:flex;gap:24px;font-size:12px;font-weight:700;letter-spacing:.08em}
.hero{height:100vh;min-height:680px;position:relative;background:url('data:image/jpeg;base64,') center 38%/cover no-repeat;display:flex;align-items:flex-end}
.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.08),rgba(0,0,0,.60))}
.hero-copy{position:relative;z-index:2;color:white;padding:0 0 4.5vh 3.5vw;max-width:520px}
.hero h1{font-size:clamp(22px,2.5vw,38px);line-height:1.35;margin:0;letter-spacing:.01em;text-shadow:0 2px 14px rgba(0,0,0,.35)}
.hero p{font-size:clamp(17px,2vw,24px);font-weight:600;margin:0}
section{padding:110px 8vw}.eyebrow{font-size:12px;letter-spacing:.22em;font-weight:800;color:#319edb;margin-bottom:22px}
h2{font-size:clamp(32px,4vw,56px);line-height:1.25;letter-spacing:-.035em;margin:0 0 38px}
.lead{max-width:800px;font-size:18px}.gray{background:#f3faff}
.message{max-width:850px}.message p{margin:0 0 18px}.signature{margin-top:38px;font-weight:700}
.members{display:flex;gap:18px;overflow-x:auto;padding-bottom:18px;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch}
.members::-webkit-scrollbar{height:7px}.members::-webkit-scrollbar-thumb{background:#bbb;border-radius:10px}
.member{flex:0 0 min(320px,72vw);aspect-ratio:4/5;background:#edf8ff;display:flex;align-items:center;justify-content:center;color:#888;font-size:13px;scroll-snap-align:start}
.business-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#ddd;border:1px solid #ddd}
.business{background:#fff;padding:38px}.num{font-size:12px;color:#888}.business h3{font-size:24px;margin:12px 0}.business p{font-size:14px;color:#555}
.recruit{text-align:center;background:linear-gradient(135deg,#eaf7ff,#cdeeff);color:#17324d}.recruit h2{max-width:760px;margin:0 auto 20px}.recruit p{margin-bottom:34px}
.btn{display:inline-block;border:1px solid currentColor;padding:16px 38px;font-weight:800;letter-spacing:.1em}
.company dl{display:grid;grid-template-columns:150px 1fr;max-width:900px;margin:0}.company dt,.company dd{padding:18px 0;border-bottom:1px solid #ddd;margin:0}
.contact{text-align:center}.contact .btn{background:#249ee4;color:#fff;border-color:#249ee4}
footer{padding:36px 8vw;background:#eaf7ff;color:#55758f;font-size:12px;display:flex;justify-content:space-between}
@media(max-width:800px){.nav{display:none}section{padding:80px 6vw}.hero-copy{padding:0 6vw 8vh}.business-grid{grid-template-columns:1fr}.company dl{grid-template-columns:1fr}.company dt{padding-bottom:0;border:0;font-weight:700}.company dd{padding-top:5px}}
.message-photo{width:100%;max-width:1100px;margin:0 auto 70px;overflow:hidden}
.message-photo img{display:block;width:100%;max-height:620px;object-fit:cover;object-position:center 34%}
.business h3,.logo,h2{color:#236fa3}
.recruit h2{font-size:clamp(24px,3vw,40px)}
.recruit .eyebrow{color:#236fa3}
@media(max-width:800px){.message-photo{margin-bottom:45px}.hero-copy{padding-left:5vw;padding-bottom:4vh}.recruit h2{font-size:26px}}

