  aspect-ratio:1/1;
  background:url("data:image/png;base64,") center/contain no-repeat;
  opacity:.07;
  pointer-events:none;
  z-index:0;
}
body > *:not(.fixed-logo-watermark){
  position:relative;
  z-index:1;
}
