/* v52: strong opening logo above gallery */
#top .opening-logo-hero{
  min-height:52vh;
  display:flex;
  align-items:center;
  justify-content:center;
  padding:42px 20px 34px;
  box-sizing:border-box;
}
#top .opening-logo-word{
  font-family:"Brush Script MT","Segoe Script","Snell Roundhand",cursive;
  font-size:clamp(76px,11vw,160px);
  font-weight:400;
  line-height:1;
  letter-spacing:-0.04em;
  color:#8fcde8;
  text-align:center;
}

/* Make the persistent background epiphany watermark a little stronger */
body::before{
  opacity:.15 !important;
}
body::after{
  opacity:.15 !important;
}

@media(max-width:768px){
  #top .opening-logo-hero{
    min-height:43vh;
    padding:28px 14px 22px;
  }
  #top .opening-logo-word{
    font-size:clamp(64px,21vw,100px);
  }
  body::before,
  body::after{
    opacity:.14 !important;
  }
}



#top{background:#fff!important;background-image:none!important}
#top .cloud-opening-stage{
 min-height:46vh!important;width:100%!important;display:flex!important;
 align-items:center!important;justify-content:center!important;
 background:#fff!important;margin:0!important;padding:0!important;
 position:relative!important;overflow:hidden!important;
}
#top .opening-cloud-logo{
 position:static!important;inset:auto!important;transform:none!important;
 width:min(68vw,720px)!important;max-width:720px!important;
 height:auto!important;opacity:.20!important;pointer-events:none!important;
 display:block!important;background-color:transparent!important;
}
#top .cloud-opening-stage::before,#top .cloud-opening-stage::after,
#top .life-gallery::before,#top .life-gallery::after,#top::before,#top::after{
 content:none!important;display:none!important;background:none!important;
}
#top .life-gallery{background:#fff!important;margin:0!important;padding-top:0!important}
.fixed-logo-watermark{opacity:.16!important}
@media(max-width:768px){
 #top .cloud-opening-stage{min-height:38vh!important}
 #top .opening-cloud-logo{width:86vw!important;opacity:.20!important}
 .fixed-logo-watermark{opacity:.15!important}
}



/* v55 force the existing cloud logo to be clearly visible above gallery */
#top .cloud-opening-stage{
  min-height:48vh!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  background:#fff!important;
  position:relative!important;
  z-index:3!important;
}
#top .cloud-opening-stage .opening-logo-visible{
  display:block!important;
  visibility:visible!important;
  opacity:1!important;
  position:static!important;
  transform:none!important;
  width:min(70vw,700px)!important;
  max-width:700px!important;
  height:auto!important;
  margin:0 auto!important;
  z-index:4!important;
}
#top .cloud-opening-stage .opening-logo-from-watermark{
  min-height:260px!important;
  background-size:contain!important;
  background-position:center!important;
  background-repeat:no-repeat!important;
}
#top .life-gallery{
  position:relative!important;
  z-index:2!important;
}
@media(max-width:768px){
 #top .cloud-opening-stage{min-height:40vh!important}
 #top .cloud-opening-stage .opening-logo-visible{width:88vw!important;max-width:430px!important}
 #top .cloud-opening-stage .opening-logo-from-watermark{min-height:190px!important}
}



/* v56: remove gap directly above auto-scroll gallery */
#top .cloud-opening-stage{
  margin-bottom:0!important;
  padding-bottom:0!important;
}
#top .cloud-opening-stage > *{
  margin-bottom:0!important;
}
#top .life-gallery{
  margin-top:0!important;
  padding-top:0!important;
}
#top .life-gallery-track,
#top .life-gallery .gallery-track,
#top .life-gallery > div{
  margin-top:0!important;
  padding-top:0!important;
}



/* v57: desktop gallery full-bleed, no left/right gap */
@media (min-width:769px){
  #top .life-gallery{
    width:100vw !important;
    max-width:none !important;
    margin-left:calc(50% - 50vw) !important;
    margin-right:calc(50% - 50vw) !important;
    padding-left:0 !important;
    padding-right:0 !important;
    overflow:hidden !important;
  }
  #top .life-gallery-track,
  #top .life-gallery .gallery-track,
  #top .life-gallery > div{
    margin-left:0 !important;
    padding-left:0 !important;
  }
}



/* v58: remove the large blank opening area shown above the gallery */
#top .cloud-opening-stage{
  min-height:0 !important;
  height:auto !important;
  padding:0 !important;
  margin:0 !important;
}
#top .cloud-opening-stage:empty{
  display:none !important;
}
#top .cloud-opening-stage .opening-logo-visible{
  margin-top:12px !important;
  margin-bottom:12px !important;
}
#top{
  min-height:0 !important;
  padding-bottom:0 !important;
}
#top .life-gallery{
  margin-top:0 !important;
  padding-top:0 !important;
}
@media(max-width:768px){
  #top .cloud-opening-stage{
    min-height:0 !important;
    height:auto !important;
  }
  #top .cloud-opening-stage .opening-logo-visible{
    margin-top:8px !important;
    margin-bottom:8px !important;
  }
}



/* v59: mobile TOP gallery higher + larger */
@media(max-width:768px){
  /* remove the opening spacer/logo stage entirely on mobile */
  #top .cloud-opening-stage{
    display:none !important;
    min-height:0 !important;
    height:0 !important;
    margin:0 !important;
    padding:0 !important;
  }
  #top{
    padding-top:0 !important;
    margin-top:0 !important;
  }
  #top .life-gallery{
    margin-top:0 !important;
    padding-top:0 !important;
    padding-bottom:8px !important;
  }

  /* make scrolling photos larger */
  #top .life-gallery img{
    width:320px !important;
    height:320px !important;
    min-width:320px !important;
    object-fit:cover !important;
  }
}
@media(max-width:390px){
  #top .life-gallery img{
    width:300px !important;
    height:300px !important;
    min-width:300px !important;
  }
}



/* v60: slightly smaller mobile gallery + faster scroll */
#top .life-gallery-track,
#top .life-gallery .gallery-track{
  animation-duration:20s !important;
}
@media(max-width:768px){
  #top .life-gallery img{
    width:270px !important;
    height:270px !important;
    min-width:270px !important;
    object-fit:cover !important;
  }
  #top .life-gallery-track,
  #top .life-gallery .gallery-track{
    animation-duration:18s !important;
  }
}
@media(max-width:390px){
  #top .life-gallery img{
    width:255px !important;
    height:255px !important;
    min-width:255px !important;
  }
}


